interface DB { person: { id: number; name: string } }
declare const db: Kysely<DB>;
const base = db.selectFrom('person').select(['id']);
// base: the accumulated row type already carries { id: number }
const a = await base.where('id', '=', 1).execute();
const b = await base.where('name', '=', 'x').execute();   // reuse: each step built a new builder
